function normalizeRelation(input:StoryRelationVersionInput):StoryRelationVersionInput{if(input.relationType==="after")return{...input,relationType:"before",sourceEventCardId:input.targetEventCardId,targetEventCardId:input.sourceEventCardId};if(["simultaneous","overlaps"].includes(input.relationType)&&input.sourceEventCardId>input.targetEventCardId)return{...input,sourceEventCardId:input.targetEventCardId,targetEventCardId:input.sourceEventCardId};return input;}
function validateRelation(input:StoryRelationVersionInput){if(input.sourceEventCardId===input.targetEventCardId)throw new NewDesignError("事件不能与自己建立时间或因果关系。",422);const temporal=["before","after","simultaneous","overlaps","contains"].includes(input.relationType);if((input.relationFamily==="temporal")!==temporal)throw new NewDesignError("关系类型与时间／因果分类不一致。",422);if(input.confidence!==undefined&&input.confidence!==null&&(input.confidence<0||input.confidence>1))throw new NewDesignError("关系置信度必须在 0 到 1 之间。",422);}
